    #[test]
    fn tiers_uniform_count_matches_modal_pair_equality_pointwise() {
        // The modal-pair form: `tiers_uniform_count() ==
        // (dominant_tier() == recessive_tier())` on every fixture —
        // including the empty map (`None == None`), every singleton-
        // support fold (`Some(t) == Some(t)`), every uniform per-tier
        // fold (`Some(first) == Some(first)` after declaration-order
        // tie-break), and every skewed fold (both sides read `false`).
        // Lifted from the trait-uniform `is_uniform_count() ==
        // (dominant_cell() == recessive_cell())` law on AxisHistogram.
        for map in [
            Prog::resolve_progressive().provenance().clone(),
            Nested::resolve_progressive().provenance().clone(),
            ProvenanceMap::default(),
        ] {
            let modal_pair_equal = map.dominant_tier() == map.recessive_tier();
            assert_eq!(map.tiers_uniform_count(), modal_pair_equal);
        }
    }

    #[test]
    fn tiers_uniform_count_empty_map_is_true() {
        // Empty-map polarity pin: the empty map has no observed cells,
        // so the uniformity predicate reads vacuously `true` — the
        // shared vacuous-uniformity boundary on the empty histogram.
        // Direct pin of the histogram-side `is_empty ⇒
        // is_uniform_count` empty convention one altitude down. Peer
        // of `kinds_uniform_count_empty_diff_is_true`.
        let empty = ProvenanceMap::default();
        assert!(empty.is_empty());
        assert!(empty.tiers_uniform_count());
        assert!(!empty.tiers_any_observed());
    }

    #[test]
    fn tiers_uniform_count_singleton_support_is_true() {
        // Singleton-support polarity pin: every leaf lands on the same
        // tier, so the one observed tier's count is both peak and
        // trough of the support — trivially uniform. Direct witness of
        // the subsumption `tiers_singular_support ⇒
        // tiers_uniform_count`. Peer of
        // `kinds_uniform_count_singleton_support_is_true`.
        let m: ProvenanceMap = ["a", "b", "c", "d"]
            .iter()
            .copied()
            .map(|k| {
                (
                    vec![k.to_owned()],
                    Provenance::computed(ConfigTierKind::Default),
                )
            })
            .collect();
        assert_eq!(m.contributing_tiers().len(), 1);
        assert!(m.tiers_singular_support());
        assert!(m.tiers_uniform_count());
    }

    #[test]
    fn tiers_uniform_count_balanced_two_tier_partial_cover_is_true() {
        // Balanced-two-tier-partial-cover polarity pin: a fold with one
        // leaf on Bare and one leaf on Default observes two cells with
        // count `1` each; the two nonzero cells share the same count,
        // so `tiers_uniform_count` reads `true`. Witness that
        // uniformity is *not* implied by full coverage: balanced
        // partial cover with matched counts is uniform too. Peer of
        // `kinds_uniform_count_balanced_two_kind_partial_cover_is_true`.
        let m: ProvenanceMap = [("b", ConfigTierKind::Bare), ("d", ConfigTierKind::Default)]
            .into_iter()
            .map(|(k, t)| (vec![k.to_owned()], Provenance::computed(t)))
            .collect();
        assert!(!m.tiers_full_cover());
        assert!(m.tiers_uniform_count());
    }

    #[test]
    fn tiers_uniform_count_uniform_four_tier_cover_is_true() {
        // Uniform-axis-cover polarity pin: a fold observing every cell
        // of ConfigTierKind exactly once has all four nonzero counts
        // at `1`. Simultaneous witness for `(tiers_full_cover,
        // tiers_uniform_count) == (true, true)` — the top uniform-
        // cover corner of the (coverage, uniformity) boolean pair on
        // the tier altitude. Peer of
        // `kinds_uniform_count_uniform_three_kind_cover_is_true` at the
        // cardinality-`4` tier altitude — one strict advance over the
        // cardinality-`3` diff altitude in the "uniform-count across
        // altitudes" projection.
        let m: ProvenanceMap = ConfigTierKind::ALL
            .iter()
            .copied()
            .map(|t| (vec![t.as_str().to_owned()], Provenance::computed(t)))
            .collect();
        assert!(m.tier_histogram().is_full_cover());
        assert!(m.tiers_full_cover());
        assert!(m.tiers_uniform_count());
    }

    #[test]
    fn tiers_uniform_count_prog_fixture_is_false() {
        // Direct pin: the Prog fold attributes 4 leaves as
        // {Bare:1, Discovered:1, Default:2, Custom:0}. Peak == 2 lands
        // on Default; trough over support == 1 on {Bare, Discovered}.
        // Spread == 1, so `tiers_uniform_count` reads `false`. Peer of
        // `tiers_balanced_prog_fixture_is_false` at the synonym seam.
        // Direct scalar-shape pin against the concrete Prog fixture.
        let r = Prog::resolve_progressive();
        assert_eq!(r.provenance().tier_spread(), 1);
        assert!(!r.provenance().tiers_uniform_count());
    }

    #[test]
    fn tiers_uniform_count_skewed_four_cell_fixture_is_false() {
        // Skewed-full-cover polarity pin: a strictly-ordered four-cell
        // fold with Bare=1, Discovered=2, Default=3, Custom=4 — peak
        // 4, trough 1, spread 3 — reads `false`. Every count distinct,
        // no tie-breaking on either side of the modal-count pair.
        // Cardinality-`4` witness one strict advance over the
        // cardinality-`3` diff-altitude skewed-three-cell fixture in
        // `kinds_uniform_count_skewed_partial_cover_is_false`.
        let m: ProvenanceMap = [
            ("b", ConfigTierKind::Bare),
            ("d1", ConfigTierKind::Discovered),
            ("d2", ConfigTierKind::Discovered),
            ("e1", ConfigTierKind::Default),
            ("e2", ConfigTierKind::Default),
            ("e3", ConfigTierKind::Default),
            ("c1", ConfigTierKind::Custom),
            ("c2", ConfigTierKind::Custom),
            ("c3", ConfigTierKind::Custom),
            ("c4", ConfigTierKind::Custom),
        ]
        .into_iter()
        .map(|(k, t)| (vec![k.to_owned()], Provenance::computed(t)))
        .collect();
        assert_eq!(m.peak_tier_count(), 4);
        assert_eq!(m.trough_tier_count(), 1);
        assert!(m.tiers_full_cover());
        assert!(!m.tiers_uniform_count());
    }

    #[test]
    fn tiers_uniform_count_empty_implies_uniform_count_pointwise() {
        // Subsumption pin: `!tiers_any_observed() ⇒
        // tiers_uniform_count()` on every fixture. Vacuous uniformity
        // on the empty map, matching the histogram-side `is_empty ⇒
        // is_uniform_count` law one altitude down.
        for map in [
            Prog::resolve_progressive().provenance().clone(),
            Nested::resolve_progressive().provenance().clone(),
            ProvenanceMap::default(),
        ] {
            if !map.tiers_any_observed() {
                assert!(
                    map.tiers_uniform_count(),
                    "empty map must land on the uniform-count boundary vacuously",
                );
            }
        }
    }

    #[test]
    fn tiers_uniform_count_singleton_support_implies_uniform_count_pointwise() {
        // Subsumption pin: `tiers_singular_support() ⇒
        // tiers_uniform_count()` on every fixture. A single observed
        // tier carries only one nonzero count to compare to itself.
        // Matches the histogram-side `has_singular_support ⇒
        // is_uniform_count` law one altitude down.
        for map in [
            Prog::resolve_progressive().provenance().clone(),
            Nested::resolve_progressive().provenance().clone(),
            ProvenanceMap::default(),
        ] {
            if map.tiers_singular_support() {
                assert!(
                    map.tiers_uniform_count(),
                    "singleton-support map must land on the uniform-count boundary vacuously",
                );
            }
        }
    }

    #[test]
    fn tiers_uniform_count_false_implies_at_least_two_contributing_tiers_pointwise() {
        // Contrapositive subsumption pin: a skewed fold has at least
        // two distinct positive counts, so its support has at least
        // two observed tiers. Lifted from the trait-uniform
        // `!is_uniform_count() ⇒ distinct_cells() >= 2` law on
        // AxisHistogram. Peer of
        // `not_kinds_uniform_count_implies_kinds_any_observed_pointwise`.
        for map in [
            Prog::resolve_progressive().provenance().clone(),
            Nested::resolve_progressive().provenance().clone(),
            ProvenanceMap::default(),
        ] {
            if !map.tiers_uniform_count() {
                assert!(
                    map.contributing_tiers().len() >= 2,
                    "non-uniform-count map must observe >= 2 contributing tiers (was {})",
                    map.contributing_tiers().len(),
                );
                assert!(
                    map.tiers_any_observed(),
                    "non-uniform-count map must be non-empty",
                );
            }
        }
    }

    #[test]
    fn tiers_uniform_count_agrees_with_hand_rolled_positive_counts_all_equal_pointwise() {
        // Parity against the exact hand-rolled positive-counts-all-
        // equal walk this climb replaces: scan the tier histogram's
        // per-cell counts vector, filter to the positive counts, and
        // check every positive count equals the first. Catches any
        // future drift where either implementation stops projecting
        // through the same distinct-positive-counts primitive. Peer of
        // `kinds_uniform_count_agrees_with_hand_rolled_positive_counts_all_equal_pointwise`.
        for map in [
            Prog::resolve_progressive().provenance().clone(),
            Nested::resolve_progressive().provenance().clone(),
            ProvenanceMap::default(),
        ] {
            let hist = map.tier_histogram();
            let mut positives = ConfigTierKind::ALL
                .iter()
                .map(|&k| hist.count(k))
                .filter(|&c| c > 0);
            let hand_rolled = match positives.next() {
                None => true,
                Some(first) => positives.all(|c| c == first),
            };
            assert_eq!(map.tiers_uniform_count(), hand_rolled);
        }
    }

    // ── Nested per-leaf attribution ──

    #[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
    struct Win {
        w: u32,
        h: u32,
    }
    #[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
    struct Nested {
        win: Win,
        theme: u32,
    }
    impl TieredConfig for Nested {
        fn bare() -> Self {
            Self {
                win: Win { w: 0, h: 0 },
                theme: 0,
            }
        }
        fn discovered() -> Self {
            Self {
                win: Win { w: 100, h: 0 },
                theme: 0,
            }
        }
        fn prescribed_default() -> Self {
            Self {
                win: Win { w: 100, h: 50 },
                theme: 7,
            }
        }
    }

    #[test]
    fn progressive_attributes_nested_leaves_independently() {
        let r = Nested::resolve_progressive();
        assert_eq!(r.value().win.w, 100);
        assert_eq!(r.value().win.h, 50);
        // win.w detected → Discovered; win.h curated → Default; sibling leaves
        // under `win` keep independent credit.
        assert_eq!(
            r.provenance().provenance_of(&["win", "w"]).unwrap().tier(),
            ConfigTierKind::Discovered,
        );
        assert_eq!(
            r.provenance().provenance_of(&["win", "h"]).unwrap().tier(),
            ConfigTierKind::Default,
        );
        assert_eq!(
            r.provenance().provenance_of(&["theme"]).unwrap().tier(),
            ConfigTierKind::Default,
        );
    }

    // ── discovered_from_layers — the low-ceremony kanchi seam ──

    struct AxisLayer {
        key: &'static str,
        val: u32,
    }
    impl DiscoveryLayer for AxisLayer {
        fn name(&self) -> &'static str {
            "axis"
        }
        fn discover(&self) -> Dict {
            let mut d = Dict::new();
            d.insert(self.key.to_owned(), Value::from(self.val));
            d
        }
    }

    // A config whose `discovered()` is wired DECLARATIVELY from layers (the
    // gap-1 seam), and whose `prescribed_default()` is built on discovered()
    // — the mado pattern, without the hand-rolled struct literal.
    #[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
    struct Seam {
        a: u32,
        b: u32,
    }
    impl TieredConfig for Seam {
        fn bare() -> Self {
            Self { a: 0, b: 0 }
        }
        fn discovered() -> Self {
            Self::discovered_from_layers(&[&AxisLayer { key: "a", val: 42 }])
        }
        fn prescribed_default() -> Self {
            let mut s = Self::discovered();
            s.b = 2;
            s
        }
    }

    #[test]
    fn discovered_from_layers_overlays_detected_axes_on_bare() {
        let d = Seam::discovered();
        assert_eq!(d.a, 42, "detected axis a overlays bare");
        assert_eq!(d.b, 0, "an axis no layer set keeps the bare floor");
    }

    #[test]
    fn discovered_from_layers_empty_stack_is_bare() {
        // Totality: no layers (or an undetectable axis) degenerates to bare.
        assert_eq!(Seam::discovered_from_layers(&[]), Seam::bare());
    }

    #[test]
    fn seam_progressive_shows_detected_axis_through_prescribed() {
        let r = Seam::resolve_progressive();
        assert_eq!(*r.value(), Seam { a: 42, b: 2 });
        assert_eq!(
            r.provenance().provenance_of(&["a"]).unwrap().tier(),
            ConfigTierKind::Discovered,
        );
        assert_eq!(
            r.provenance().provenance_of(&["b"]).unwrap().tier(),
            ConfigTierKind::Default,
        );
    }

    // ── Provenance primitive surface ──

    #[test]
    fn provenance_display_is_typed() {
        assert_eq!(
            Provenance::computed(ConfigTierKind::Discovered).to_string(),
            "discovered"
        );
        assert_eq!(
            Provenance::file("/x.yaml").to_string(),
            "custom (file: /x.yaml)"
        );
        assert_eq!(Provenance::env("APP_").to_string(), "custom (env: APP_)");
    }

    #[test]
    fn provenance_tier_ordinal_reuses_closed_axis_order() {
        // Precedence reuses the const ConfigTierKind ClosedAxis declaration
        // order — Bare < Discovered < Default < Custom.
        assert!(
            Provenance::computed(ConfigTierKind::Bare).tier_ordinal()
                < Provenance::computed(ConfigTierKind::Discovered).tier_ordinal()
        );
        assert!(
            Provenance::computed(ConfigTierKind::Discovered).tier_ordinal()
                < Provenance::computed(ConfigTierKind::Default).tier_ordinal()
        );
        assert!(
            Provenance::computed(ConfigTierKind::Default).tier_ordinal()
                < Provenance::file("/x").tier_ordinal()
        );
    }

    // ── resolve_progressive_full — the end-to-end fused chain ──
    //
    // Fuses the three computed tiers with real file + env overlays read
    // through the ProviderChain figment fold. A String field keeps the env
    // overlay coercion-free; a u32 field exercises the file numeric path.
    //
    // Restored 2026-08-06: the method + its tests were authored on
    // `feat/kube-cluster-discovery` (45091d6) and dropped by the merge
    // `011f4ad`, which resolved src/tiered.rs in favour of main while the
    // CLAUDE.md claim came through from the feature side — leaving the doc
    // asserting a SHIPPED function that did not exist.

    #[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
    struct Fused {
        name: String,
        size: u32,
    }
    impl TieredConfig for Fused {
        fn bare() -> Self {
            Self {
                name: String::new(),
                size: 0,
            }
        }
        fn discovered() -> Self {
            Self {
                name: "disc".to_owned(),
                size: 1,
            }
        }
        fn prescribed_default() -> Self {
            Self {
                name: "disc".to_owned(),
                size: 9,
            }
        }
    }

    #[test]
    fn resolve_progressive_full_reads_a_real_file_over_the_computed_tiers() {
        let dir = tempfile::TempDir::new().unwrap();
        let file = dir.path().join("fused.yaml");
        std::fs::write(&file, "size: 42\n").unwrap();

        let r = Fused::resolve_progressive_full(Some(&file), None);
        // File beats prescribed (9); name untouched by the file → from discovered.
        assert_eq!(r.value().size, 42);
        assert_eq!(r.value().name, "disc");
        let prov = r.provenance().provenance_of(&["size"]).unwrap();
        assert_eq!(prov.tier(), ConfigTierKind::Custom);
        assert_eq!(prov.source(), &ConfigSource::File(file.clone()));
        // The untouched leaf keeps its computed-tier credit.
        assert_eq!(
            r.provenance().provenance_of(&["name"]).unwrap().tier(),
            ConfigTierKind::Discovered,
        );
    }

    #[test]
    fn resolve_progressive_full_reads_a_real_env_overlay() {
        let prefix = "SHIKUMI_FUSED_ENV_";
        // SAFETY: single-threaded test; prefix is unique to this test so a
        // parallel sibling cannot observe it; removed immediately below.
        unsafe { std::env::set_var("SHIKUMI_FUSED_ENV_NAME", "fromenv") };
        let r = Fused::resolve_progressive_full(None, Some(prefix));
        unsafe { std::env::remove_var("SHIKUMI_FUSED_ENV_NAME") };

        assert_eq!(r.value().name, "fromenv", "env overlay beats prescribed");
        let prov = r.provenance().provenance_of(&["name"]).unwrap();
        assert_eq!(prov.tier(), ConfigTierKind::Custom);
        assert_eq!(prov.source(), &ConfigSource::Env(prefix.to_owned()));
    }

    #[test]
    fn resolve_progressive_full_env_beats_file_on_a_shared_leaf() {
        let dir = tempfile::TempDir::new().unwrap();
        let file = dir.path().join("fused.yaml");
        // File sets BOTH name and size; env re-sets name.
        std::fs::write(&file, "name: fromfile\nsize: 42\n").unwrap();
        let prefix = "SHIKUMI_FUSED_SHARED_";
        // SAFETY: as above — unique prefix, removed immediately.
        unsafe { std::env::set_var("SHIKUMI_FUSED_SHARED_NAME", "fromenv") };

        let r = Fused::resolve_progressive_full(Some(&file), Some(prefix));
        unsafe { std::env::remove_var("SHIKUMI_FUSED_SHARED_NAME") };

        // env is folded after file (both Custom rank, file-then-env order) → wins.
        assert_eq!(r.value().name, "fromenv");
        // size only the file set → file wins, and is told apart by source.
        assert_eq!(r.value().size, 42);
        assert_eq!(
            r.provenance().provenance_of(&["name"]).unwrap().source(),
            &ConfigSource::Env(prefix.to_owned()),
        );
        assert_eq!(
            r.provenance().provenance_of(&["size"]).unwrap().source(),
            &ConfigSource::File(file.clone()),
        );
    }

    #[test]
    fn resolve_progressive_full_missing_file_is_crash_safe_noop() {
        // A missing file contributes an empty overlay — the fused result equals
        // the plain computed fold, never a panic.
        let r = Fused::resolve_progressive_full(Some(Path::new("/nope/absent.yaml")), None);
        let base = Fused::resolve_progressive();
        assert_eq!(r.value(), base.value());
        // The computed tiers still fully credit every leaf.
        assert_eq!(
            r.provenance().provenance_of(&["name"]).unwrap().tier(),
            ConfigTierKind::Discovered,
        );
    }

    #[test]
    fn resolve_progressive_full_malformed_file_is_crash_safe_noop() {
        // Distinct from the MISSING case: the file exists and parses to
        // garbage. `from_file` must still degrade to an empty overlay rather
        // than propagate — otherwise the fused chain is not total.
        let dir = tempfile::TempDir::new().unwrap();
        let file = dir.path().join("broken.yaml");
        std::fs::write(&file, "size: [not, a, number\n").unwrap();

        let r = Fused::resolve_progressive_full(Some(&file), None);
        let base = Fused::resolve_progressive();
        assert_eq!(r.value(), base.value(), "malformed file must not apply");
    }

    #[test]
    fn from_file_missing_path_yields_empty_dict_with_file_provenance() {
        let layer = ProgressiveLayer::from_file("/nope/absent.yaml");
        assert!(layer.dict().is_empty(), "missing file ⇒ empty overlay");
        assert_eq!(
            layer.provenance().source(),
            &ConfigSource::File("/nope/absent.yaml".into()),
        );
    }

    #[test]
    fn from_file_is_the_lenient_peer_of_try_from_file() {
        // The pair must disagree ONLY on the failure mode. A test that checked
        // just the happy path would pass even if `from_file` were a plain
        // alias, so the disagreement is asserted directly.
        //
        // MEASURED, and not what the signatures suggest: a MISSING file is
        // already Ok(empty) on BOTH sides — figment's `Yaml::file()` is a
        // silent no-op when the path does not exist, so `try_from_file`'s
        // `Result` never fires for absence. The genuine divergence is a file
        // that EXISTS and fails to parse. Pinned here so nobody "simplifies"
        // `from_file` away on the assumption it only guards absence.
        let missing = Path::new("/nope/absent.yaml");
        assert!(
            ProgressiveLayer::try_from_file(missing).is_ok(),
            "a missing file is not an error at the figment layer",
        );
        assert!(ProgressiveLayer::from_file(missing).dict().is_empty());

        let dir = tempfile::TempDir::new().unwrap();

        // The real divergence: malformed → try_ errors, lenient degrades.
        let bad = dir.path().join("bad.yaml");
        std::fs::write(&bad, "size: [not, a, number\n").unwrap();
        assert!(
            ProgressiveLayer::try_from_file(&bad).is_err(),
            "a malformed file MUST be an error on the fallible side",
        );
        assert!(
            ProgressiveLayer::from_file(&bad).dict().is_empty(),
            "…and an empty overlay on the lenient side",
        );

        // …and they agree exactly on a good file.
        let file = dir.path().join("ok.yaml");
        std::fs::write(&file, "size: 7\n").unwrap();
        assert_eq!(
            ProgressiveLayer::from_file(&file).dict(),
            ProgressiveLayer::try_from_file(&file).unwrap().dict(),
        );
    }

    #[test]
    fn from_env_unset_prefix_yields_empty_dict_with_env_provenance() {
        let layer = ProgressiveLayer::from_env("SHIKUMI_DEFINITELY_UNSET_PREFIX_");
        assert!(layer.dict().is_empty(), "unset prefix ⇒ empty overlay");
        assert_eq!(
            layer.provenance().source(),
            &ConfigSource::Env("SHIKUMI_DEFINITELY_UNSET_PREFIX_".to_owned()),
        );
    }

    #[test]
    fn progressive_try_from_file_reads_yaml_via_provider_chain() {
        // The fusion constructor lets the caller point at a YAML path
        // instead of hand-building a Dict: the file is parsed via
        // ProviderChain::with_file (same format detection), the resulting
        // overlay carries Provenance::file(path), and the leaf it wins in
        // the progressive fold is stamped with that file's ConfigSource.
        // Before this constructor, the caller had to open the file,
        // deserialize it, and re-insert values into a Dict by hand.
        let dir = tempfile::TempDir::new().unwrap();
        let path = dir.path().join("prog.yaml");
        std::fs::write(&path, "b: 99\n").unwrap();

        let layer = ProgressiveLayer::try_from_file(&path).unwrap();
        let r = Prog::resolve_progressive_with(&[layer]);

        assert_eq!(r.value().b, 99, "file overlay beats prescribed b=20");
        let prov = r.provenance().provenance_of(&["b"]).unwrap();
        assert_eq!(prov.tier(), ConfigTierKind::Custom);
        assert_eq!(prov.source(), &ConfigSource::File(path.clone()));
        // A leaf the file didn't touch keeps its computed-tier provenance.
        assert_eq!(
            r.provenance().provenance_of(&["a"]).unwrap().tier(),
            ConfigTierKind::Discovered
        );
    }

    #[test]
    fn progressive_try_from_file_and_provider_chain_agree_on_format_detection() {
        // The load-bearing fusion invariant: the same TOML file, ingested
        // through the two paths, yields byte-identical resolved values on
        // every leaf the file sets. A drift here would mean an operator
        // migrating from ProviderChain to resolve_progressive_with sees
        // different parses of the same on-disk bytes — the exact seam the
        // fusion is meant to close.
        let dir = tempfile::TempDir::new().unwrap();
        let path = dir.path().join("prog.toml");
        std::fs::write(&path, "b = 77\nc = 44\n").unwrap();

        let via_progressive =
            Prog::resolve_progressive_with(&[ProgressiveLayer::try_from_file(&path).unwrap()]);
        let via_chain: Prog = ProviderChain::new()
            .with_defaults(&Prog::prescribed_default())
            .with_file(&path)
            .extract()
            .unwrap();

        assert_eq!(via_progressive.value().b, via_chain.b);
        assert_eq!(via_progressive.value().c, via_chain.c);
    }

    #[test]
    fn progressive_try_from_file_malformed_returns_extract_error() {
        // A file whose bytes don't parse as the declared format surfaces
        // as ShikumiError::Extract with the ConfigSource::File chain
        // recorded, so the operator sees the failing file identity
        // without a separate try/log/wrap dance. (A *missing* file is
        // silently an empty overlay: figment's file providers are
        // optional-by-default, matching ProviderChain::with_file's own
        // semantics — the fusion faithfully inherits that contract.)
        let dir = tempfile::TempDir::new().unwrap();
        let path = dir.path().join("prog.yaml");
        std::fs::write(&path, "b: [unterminated\n").unwrap();
        let err = ProgressiveLayer::try_from_file(&path).unwrap_err();
        assert!(
            matches!(err, ShikumiError::Extract { .. }),
            "malformed-yaml error must be a ShikumiError::Extract; got {err:?}"
        );
        if let ShikumiError::Extract { sources, .. } = &err {
            assert!(
                sources
                    .iter()
                    .any(|s| matches!(s, ConfigSource::File(p) if p == &path)),
                "Extract error must carry the failing file in its source chain; got {sources:?}"
            );
        }
    }

    #[test]
    fn progressive_from_env_stamps_env_provenance() {
        // The env-side fusion peer: an env prefix produces an overlay
        // whose leaves are stamped Provenance::env(prefix). Uses a unique
        // prefix so parallel test runs don't collide on env state.
        let prefix = "SHIKUMI_TIERED_ENV_TEST_";
        let var = "SHIKUMI_TIERED_ENV_TEST_B";
        // SAFETY: env access is guarded by a unique prefix; the cleanup
        // below runs on every path.
        unsafe { std::env::set_var(var, "555") };

        let layer = ProgressiveLayer::from_env(prefix);
        let r = Prog::resolve_progressive_with(&[layer]);

        unsafe { std::env::remove_var(var) };

        assert_eq!(r.value().b, 555, "env overlay beats prescribed b=20");
        let prov = r.provenance().provenance_of(&["b"]).unwrap();
        assert_eq!(prov.tier(), ConfigTierKind::Custom);
        assert_eq!(prov.source(), &ConfigSource::Env(prefix.to_owned()));
    }

    #[test]
    fn progressive_from_env_empty_prefix_degenerates_to_no_op() {
        // No env vars match the (unique) prefix → the overlay contributes
        // an empty dict → the fold behaves exactly as
        // resolve_progressive() would without any overlay, matching
        // ProviderChain::with_env's "no matches → identity layer"
        // semantics. Regression protection for the infallible-but-honest
        // contract on from_env.
        let baseline = Prog::resolve_progressive();
        let with_empty = Prog::resolve_progressive_with(&[ProgressiveLayer::from_env(
            "SHIKUMI_TIERED_ENV_UNMATCHED_PREFIX_",
        )]);
        assert_eq!(baseline.value(), with_empty.value());
    }

    #[test]
    fn provenance_discovered_helper_matches_computed_discovered() {
        // The discovered() helper closes the tier-axis constructor grid on
        // Provenance at one site: file/env are the operator-overlay
        // constructors, discovered is the runtime-computed-overlay peer.
        // Its identity is the same (tier: Discovered, source: Defaults)
        // pair every prior discovered-tier caller composed by hand as
        // computed(ConfigTierKind::Discovered); lifting it to a named
        // constructor gives the future ConfigSource::Discovered refinement
        // a single seam to thread through.
        assert_eq!(
            Provenance::discovered(),
            Provenance::computed(ConfigTierKind::Discovered)
        );
        assert_eq!(Provenance::discovered().tier(), ConfigTierKind::Discovered);
        assert_eq!(Provenance::discovered().source(), &ConfigSource::Defaults);
        assert_eq!(Provenance::discovered().to_string(), "discovered");
    }

    #[test]
    fn provenance_bare_helper_matches_computed_bare() {
        // The bare() helper closes the tier-axis constructor grid on
        // Provenance on the FIRST computed-defaults row (Bare + Defaults),
        // peer of discovered() on the middle row and prescribed_default()
        // on the last row. Its identity is the same (tier: Bare, source:
        // Defaults) pair every prior bare-tier caller — including the
        // canonical fold seam at TieredConfig::resolve_progressive_with —
        // hand-composed as computed(ConfigTierKind::Bare). All four
        // observable facets (equality, tier, source, Display) must agree
        // with the manual composition, so the constructor is a
        // zero-behavior-change closure of a hand-written idiom.
        assert_eq!(
            Provenance::bare(),
            Provenance::computed(ConfigTierKind::Bare)
        );
        assert_eq!(Provenance::bare().tier(), ConfigTierKind::Bare);
        assert_eq!(Provenance::bare().source(), &ConfigSource::Defaults);
        assert_eq!(Provenance::bare().to_string(), "bare");
    }

    #[test]
    fn provenance_prescribed_default_helper_matches_computed_default() {
        // The prescribed_default() helper closes the tier-axis
        // constructor grid on Provenance on the LAST computed-defaults row
        // (Default + Defaults), peer of bare() on the first row and
        // discovered() on the middle row. Named after the trait method
        // rather than the tier variant (`Default`) to keep the identity
        // unambiguous vs the Rust std::default::Default convention. All
        // four observable facets (equality, tier, source, Display) must
        // agree with the manual composition computed(ConfigTierKind::Default),
        // so the constructor is a zero-behavior-change closure of the
        // hand-written idiom at the ~15 prior call sites (the fold seam
        // plus a dozen recessive-tier diff pins in the tiered.rs test
        // module) that composed it by hand.
        assert_eq!(
            Provenance::prescribed_default(),
            Provenance::computed(ConfigTierKind::Default)
        );
        assert_eq!(
            Provenance::prescribed_default().tier(),
            ConfigTierKind::Default
        );
        assert_eq!(
            Provenance::prescribed_default().source(),
            &ConfigSource::Defaults
        );
        assert_eq!(Provenance::prescribed_default().to_string(), "default");
    }

    #[test]
    fn provenance_into_parts_round_trips_through_new() {
        // The consuming destructuring accessor is the exact inverse of
        // Provenance::new on the same (tier, source) pair: destructuring
        // a Provenance via into_parts and rebuilding it via new recovers
        // the original provenance byte-identically. The pair is atomic on
        // the ownership boundary — the two fields move together out of
        // the struct and back in, mirroring the round-trip
        // ProgressiveLayer::into_parts + ProgressiveLayer::new already
        // pins one seam up on the atomic-pair boundary the container
        // level carries.
        let prov = Provenance::file("/etc/into_parts_prim.yaml");
        let (out_tier, out_source) = prov.clone().into_parts();
        assert_eq!(out_tier, ConfigTierKind::Custom);
        assert_eq!(
            out_source,
            ConfigSource::File(PathBuf::from("/etc/into_parts_prim.yaml"))
        );
        let rebuilt = Provenance::new(out_tier, out_source);
        assert_eq!(rebuilt, prov);
    }

    #[test]
    fn provenance_into_parts_matches_field_accessors() {
        // The load-bearing pointwise invariant behind the atomic-pair
        // ownership-boundary closure on the primitive: `prov.clone().into_parts()`
        // is equal to `(prov.tier(), prov.source().clone())` — the two
        // spellings a caller has for taking the (tier, source) pair out
        // of a Provenance, one hand-rolled through the borrow accessors,
        // one named on the atomic-pair boundary. Same field-wise clone
        // cost (source is owned; tier is Copy), same output pair. Without
        // this pin, a future edit to `Clone for Provenance` (e.g. adding
        // an interned identity or a source watermark) could silently
        // diverge the two paths and callers routing through into_parts
        // would see a different pair than callers doing the manual
        // accessor-clone dance.
        let prov = Provenance::env("SHIKUMI_PROVENANCE_INTO_PARTS_");
        let via_into_parts = prov.clone().into_parts();
        let via_accessors = (prov.tier(), prov.source().clone());
        assert_eq!(via_into_parts, via_accessors);
    }

    #[test]
    fn provenance_from_tuple_agrees_with_into_parts() {
        // The std-trait facade on the primitive's ownership boundary:
        // the `From<Provenance> for (ConfigTierKind, ConfigSource)` impl
        // and the inherent `into_parts` method produce the same pair on
        // every input. Callers routing through `Into::into` /
        // `<(ConfigTierKind, ConfigSource)>::from(prov)` hit the same
        // destructuring as callers naming the inherent method — the two
        // spellings are one operation, not a facade with drift, so a
        // downstream generic bound `T: Into<(ConfigTierKind, ConfigSource)>`
        // picks up Provenance for free.
        let prov = Provenance::file("/etc/from_tuple_prim.yaml");
        let via_method = prov.clone().into_parts();
        let via_from: (ConfigTierKind, ConfigSource) = prov.into();
        assert_eq!(via_method, via_from);
    }

    #[test]
    fn provenance_from_pair_agrees_with_new() {
        // The reconstruction dual of provenance_from_tuple_agrees_with_into_parts:
        // the `From<(ConfigTierKind, ConfigSource)> for Provenance` impl
        // and the inherent `Provenance::new` constructor produce the same
        // provenance on every input pair. Together with the two
        // destructuring-side impls above, this closes BOTH directions of
        // the atomic-pair ownership boundary on the primitive — a
        // Provenance round-trips through the (tier, source) pair via
        // either the inherent [new, into_parts] pair or the two From
        // facades and lands at the identical byte-image. A ConfigPlane
        // broadcast surface receiving a wire-encoded (tier, source)
        // tuple can decode it via one `.into()` call and no caller has to
        // reach for the inherent constructor name to satisfy a generic
        // `T: Into<Provenance>` bound.
        let pair = (
            ConfigTierKind::Custom,
            ConfigSource::File(PathBuf::from("/etc/from_pair_prim.yaml")),
        );
        let via_new = Provenance::new(pair.0, pair.1.clone());
        let via_from: Provenance = pair.clone().into();
        assert_eq!(via_new, via_from);
        // And round-tripping in both directions lands byte-identically —
        // proof the two From impls are inverses on the atomic pair.
        let round_tripped: (ConfigTierKind, ConfigSource) = via_from.into();
        assert_eq!(round_tripped, pair);
    }

    #[test]
    fn resolve_progressive_fold_seam_stamps_named_tier_provenance() {
        // End-to-end pin on the fold seam. The three trait tiers seed the
        // fold at TieredConfig::resolve_progressive_with with provenances
        // that must be byte-identical (equality + Display) to the three
        // named Provenance constructors on the computed-defaults row:
        // Provenance::bare() / discovered() / prescribed_default(). This
        // is the load-bearing invariant of the seam refactor — the fold's
        // provenance-construction identity now flows through the named
        // constructors, so any future richer source variant added to a
        // computed-defaults tier propagates through the whole fold via
        // ONE seam (the tier's Provenance constructor) instead of the
        // three unpacked `computed(ConfigTierKind::_)` literals the seam
        // previously carried. A leaf pinned at each of the three tiers
        // proves each named constructor is the effective identity the
        // fold hands out to callers.
        #[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
        struct TierSeamFixture {
            b: u32,
            d: u32,
            p: u32,
        }
        impl TieredConfig for TierSeamFixture {
            fn bare() -> Self {
                Self { b: 11, d: 0, p: 0 }
            }
            // Each tier PRESERVES the fields the tier below already set
            // (b in discovered; b and d in prescribed_default) so the
            // last-changer rule credits each field to the FIRST tier that
            // set it to its final value — the seam's per-tier attribution
            // then reads pointwise off the three named constructors.
            fn discovered() -> Self {
                Self { b: 11, d: 22, p: 0 }
            }
            fn prescribed_default() -> Self {
                Self {
                    b: 11,
                    d: 22,
                    p: 33,
                }
            }
        }
        let r = TierSeamFixture::resolve_progressive();
        // Each field's provenance is exactly the named constructor for its
        // tier — the seam's per-leaf attribution matches the constructor
        // grid pointwise.
        let bare_p = r.provenance().provenance_of(&["b"]).unwrap();
        assert_eq!(bare_p, &Provenance::bare());
        assert_eq!(bare_p.to_string(), "bare");
        let disc_p = r.provenance().provenance_of(&["d"]).unwrap();
        assert_eq!(disc_p, &Provenance::discovered());
        assert_eq!(disc_p.to_string(), "discovered");
        let default_p = r.provenance().provenance_of(&["p"]).unwrap();
        assert_eq!(default_p, &Provenance::prescribed_default());
        assert_eq!(default_p.to_string(), "default");
        // And the seam continues to produce the same folded value as the
        // legacy hand-composed seam did — proven by every existing
        // resolve_progressive test in this module continuing to pass, plus
        // this pointwise check on the fixture.
        assert_eq!(
            r.value(),
            &TierSeamFixture {
                b: 11,
                d: 22,
                p: 33
            }
        );
    }

    #[test]
    fn progressive_layer_discovered_stamps_discovered_provenance() {
        // The overlay's structural contract: provenance is
        // Provenance::discovered() (tier Discovered, source Defaults —
        // the same layer-kind partition Provider::with_discovered records),
        // and the overlay's dict is the caller's Dict verbatim. This is
        // the tier-axis peer of the operator-overlay identity the
        // file / env constructors already close at one site.
        let mut dict = Dict::new();
        dict.insert("c".to_owned(), Value::from(77_u32));
        let overlay = ProgressiveLayer::discovered(dict.clone());
        assert_eq!(overlay.provenance(), &Provenance::discovered());
        assert_eq!(overlay.provenance().tier(), ConfigTierKind::Discovered);
        assert_eq!(overlay.provenance().source(), &ConfigSource::Defaults);
        assert_eq!(overlay.dict(), &dict);
    }

    #[test]
    fn progressive_layer_discovered_overlay_survives_fold_as_discovered() {
        // End-to-end: a Discovered overlay's leaf value survives to the
        // resolved config and is attributed to Discovered — the
        // last-changer rule requires the value the overlay writes to agree
        // with the value prescribed_default() would emit (so
        // prescribed_default() skips at step 4 and the Discovered
        // attribution from step 3 stands). The fixture below is the
        // minimal shape that exercises exactly this seam: bare == 0,
        // discovered == 0 (no self-contribution), prescribed_default ==
        // 99, overlay == 99. Without ProgressiveLayer::discovered the
        // caller would hand-build `ProgressiveLayer::new(
        // Provenance::computed(ConfigTierKind::Discovered), dict)` — the
        // constructor closes that composition at one site.
        #[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
        struct DiscOverlay {
            x: u32,
        }
        impl TieredConfig for DiscOverlay {
            fn bare() -> Self {
                Self { x: 0 }
            }
            fn prescribed_default() -> Self {
                Self { x: 99 }
            }
        }
        let mut dict = Dict::new();
        dict.insert("x".to_owned(), Value::from(99_u32));
        let overlay = ProgressiveLayer::discovered(dict);
        let r = DiscOverlay::resolve_progressive_with(&[overlay]);
        assert_eq!(r.value().x, 99);
        let prov = r.provenance().provenance_of(&["x"]).unwrap();
        assert_eq!(prov.tier(), ConfigTierKind::Discovered);
        assert_eq!(prov.source(), &ConfigSource::Defaults);
    }

    #[test]
    fn progressive_layer_discovered_from_layers_matches_compose() {
        // The fusion peer of try_from_file / from_env on the discovered
        // tier: the caller passes a DiscoveryLayer stack, and the
        // constructor runs compose(layers) at the seam. The load-bearing
        // invariant is that the overlay's dict is exactly what compose
        // would produce on the same input — a caller ingesting a layer
        // stack through resolve_progressive_with(&[discovered_from_layers(&L)])
        // and one wiring the same stack through
        // TieredConfig::discovered_from_layers cannot drift on discovery
        // composition.
        let layers: &[&dyn DiscoveryLayer] = &[&AxisLayer { key: "a", val: 33 }];
        let overlay = ProgressiveLayer::discovered_from_layers(layers);
        assert_eq!(overlay.provenance(), &Provenance::discovered());
        assert_eq!(overlay.dict(), &compose(layers));
    }

    #[test]
    fn progressive_layer_discovered_from_layers_empty_stack_is_no_op() {
        // Totality: an empty layer stack (or a stack whose every
        // discover() returns an empty dict) degenerates to an empty-dict
        // overlay — the fold-side identity, matching
        // compose(&[]).is_empty() at the source. Regression protection
        // for the discovered-tier peer of from_env's unmatched-prefix
        // identity.
        let baseline = Prog::resolve_progressive();
        let with_empty =
            Prog::resolve_progressive_with(&[ProgressiveLayer::discovered_from_layers(&[])]);
        assert_eq!(baseline.value(), with_empty.value());
        assert_eq!(baseline.provenance(), with_empty.provenance());
    }

