    #[test]
    fn peak_source_kind_count_uniform_cover_is_one() {
        // Trait-uniform invariant lifted to the ProvenanceMap surface:
        // on a full-cover fold where every source-kind observes the same
        // nonzero count of one, the peak count is `1`. Direct
        // construction: one leaf per source-kind, full-cover with
        // uniform count 1. Peer of
        // `dominant_source_kind_uniform_cover_picks_first_cell` on the
        // count side (that test pins the *cell*; this test pins the
        // *count*). Together the pair `(dominant_source_kind,
        // peak_source_kind_count)` reads `(Some(Defaults), 1)` on the
        // uniform-cover fold. Source-altitude peer of
        // `peak_tier_count_uniform_cover_is_one`.
        let m: ProvenanceMap = crate::ConfigSourceKind::ALL
            .iter()
            .copied()
            .map(|k| {
                let p = match k {
                    crate::ConfigSourceKind::Defaults => Provenance::bare(),
                    crate::ConfigSourceKind::Env => Provenance::env("PFX_"),
                    crate::ConfigSourceKind::File => Provenance::file("/etc/x.yaml"),
                };
                (vec![k.as_str().to_owned()], p)
            })
            .collect();
        assert!(m.source_kind_histogram().is_full_cover());
        assert_eq!(m.peak_source_kind_count(), 1);
    }

