    #[test]
    fn source_kinds_strictly_modally_unique_strict_partition_on_non_empty_pointwise() {
        // Strict modal partition pin: on every non-empty map exactly one
        // of `(source_kinds_strictly_modally_unique,
        // source_kinds_modally_tied)` fires; both read `false` on the
        // empty map — the shared boundary below both branches of the
        // strict modal partition. Direct pin of the histogram-side
        // strict modal partition
        // `!is_empty ⇒ is_strictly_modally_unique ⇔ !is_modally_tied`
        // one altitude down, now phrased as an XOR on the two named
        // source-kind-altitude seams at the surface.
        for map in [
            Prog::resolve_progressive().provenance().clone(),
            source_kind_histogram_mixed_fixture().provenance().clone(),
            ProvenanceMap::default(),
        ] {
            let unique = map.source_kinds_strictly_modally_unique();
            let tied = map.source_kinds_modally_tied();
            if map.is_empty() {
                assert!(!unique);
                assert!(!tied);
            } else {
                assert_ne!(unique, tied);
            }
        }
    }

    #[test]
    fn source_kinds_strictly_modally_unique_agrees_with_open_coded_peak_multiplicity_walk_pointwise()
     {
        // Parity against the exact hand-rolled open-coded peak-
        // multiplicity walk this lift replaces: scan the histogram's
        // per-cell counts vector, track the running max + reset-on-rise
        // modal multiplicity, then read `peak_mult == 1` off the
        // equality. Catches any future drift where either implementation
        // stops projecting through the same peak-multiplicity scan on
        // the underlying counts.
        for map in [
            Prog::resolve_progressive().provenance().clone(),
            source_kind_histogram_mixed_fixture().provenance().clone(),
            ProvenanceMap::default(),
        ] {
            let hist = map.source_kind_histogram();
            let mut max = 0usize;
            let mut peak_mult = 0usize;
            for k in crate::ConfigSourceKind::ALL {
                let c = hist.count(*k);
                if c == 0 {
                    continue;
                }
                if c > max {
                    max = c;
                    peak_mult = 1;
                } else if c == max {
                    peak_mult += 1;
                }
            }
            assert_eq!(map.source_kinds_strictly_modally_unique(), peak_mult == 1,);
        }
    }

